class rtc(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def open_rtc_connection(self, ip="192.168.1.2"):
        """
        Keyword to open connection to RTC server
        :param ip: ip address of the rtc server
        """
        self._tma = RtcConnection(ip)

    def open_the_tma_in_given_mode(self, tma_type=1, tma_path=None, mci_port=None,
                                   aci_port=None, tma_profile=None):
        """
        Keyword to open the tma for controlling E500 UE simulator
        :param tma_type: 0 = Ex-MUE Mode, 1 = E500 Mode
        :type tma_type int
        :param tma_path: Optional Parameter. Absolute path of folder containing TmaApplication.exe
        :type tma_path: str
        :param mci_port: OptionalParameter to connect toTMA MCI or RCI proxyport: default 5003
        :type mci_port: int
        :param aci_port: Optional Parameter to connect to TMA ACI proxy port: default: int 5030
        :type aci_port: int
        :param tma_profile: Optional Parameter to open TMA with a profile
        :type tma_profile: str
        """
        return self._tma.open_the_tma_in_given_mode(tma_type, tma_path, mci_port,
                                                    aci_port, tma_profile)

    def close_the_tma(self):
        """
        Keyword to close the tma
        """
        return self._tma.close_the_tma()

    def close_all_instances_of_tma(self):
        """
        Keyword to close all open tma instanses
        """
        return self._tma.close_all_instances_of_tma()

    def get_all_opened_tmas(self):
        """
        Keyword returns id from all opened tma instanses
        """
        return self._tma.get_all_opened_tmas()

    def get_path_to_tma_executable(self):
        """
        Keyword returns the path where tma is opened
        """
        return self._tma.get_path_to_tma_executable()

    def schedule_campaign(self, campaign_path, iteration_count=1, action_on_event=2,
                          date=None, time=None):
        """
        Keyword add campaign to tma campaign scheduler. This keyword returns cheduled campaign name
        and this name is used to start the test run.
        :param campaign_path: the path to where the campaign to be launched is located in e500 control pc
        :param iteration_count: default 1: range 0 - 65535
        :type iteration_count: int
        :param action_on_event: default 2: 0 = Stop, 1 = Continue, 2 = Continue to Next
        :type action_on_event: int
        :date :DATE parameters are mandatory when a Campaign needs to be time scheduled.
        :type date str: DATE: format shall be as per the local system date format
        :time :TIME parameters are mandatory when a Campaign needs to be time scheduled.
        :type time str: TIME: format shall be as per the local system date format
        """
        return self._tma.schedule_campaign(campaign_path, iteration_count, action_on_event,
                                           date, time)

    def run_a_scheduled_e500_campaign(self, campaign_name, add_to_active_scheduler=None):
        """
        Keyword run a scheduled campaign.
        :param campaign_name: e.g newcampaign_190104_111722373
        :type campaign_name: str
        :param add_to_active_scheduler: Optional parameter to add the run to active scheduler
         range 0-1
        :type add_to_active_scheduler: int
        """
        return self._tma.run_a_scheduled_e500_campaign(campaign_name, add_to_active_scheduler)

    def provide_running_state_of_campaign_run(self):
        """
        Keyword provide running status of run.
        E.g: AUTOMATION_RUN Start, AUTOMATION_RUN PROGRESS, AUTOMATION_RUN Complete
        with the latest % complete indication.
        """
        return self._tma.provide_running_state_of_campaign_run()

    def stop_a_running_e500_campaign(self):
        """
        Keyword stops a running campaign.
        """
        return self._tma.stop_a_running_e500_campaign()

    def execute_mci_command(self, cmd, cmd_timeout=2):
        """
        Keyword execute mci command and return response.
        :param cmd: Cmd example: forw mte  GetStats [ALL] [COMBINED] [COMBINED]
        :type cmd: str
        :param cmd_timeout: default 2
        :type cmd_timeout: int
        """
        return self._tma.execute_mci_command(cmd, cmd_timeout)

    def generate_report_of_executed_campaign(self, campaign_name):
        """
        Keyword generates report of executed campaign.
        The report has statistics on the test
        :param campaign_name: name from which the report will be created
        :type campaign_name str
        """
        return self._tma.generate_report_of_executed_campaign(campaign_name)

    def get_report_generation_progress(self):
        """
        Keyword returns  Latest indication indicating report generation
        progress and path where report exist in e500 control pc.
        """
        return self._tma.get_report_generation_progress()

    def schedule_and_start_test_run_on_extmue(self, campaign_path, iteration_count=1, action_on_event=2,
                                              date=None, time=None):
        """
        Keyword schedule and start run with Ex-MUE tma mode.
        :param campaign_path: the path to where the campaign to be launched is located in e500 control pc
        :type campaign_path: str
        :param: iteration_count: default 1: range 0 - 65535
        :type iteration_count: int
        :param action_on_event: default 0: 0 = Stop, 1 = Continue
        :type action_on_event: int
        """
        return self._tma.schedule_and_start_test_run_on_extmue(campaign_path, iteration_count, action_on_event,
                                                               date, time)

    def stop_a_running_extmue_campaign(self):
        """
        Keyword stops a running campaign.
        """
        return self._tma.stop_a_running_extmue_campaign()

    def get_running_status_of_a_test_on_extmue(self):
        """
        Keyword provide running status of run.
        E.g: AUTOMATION_RUN Start, AUTOMATION_RUN PROGRESS, AUTOMATION_RUN Complete
        with the latest % complete indication.
        """
        return self._tma.get_running_status_of_a_test_on_extmue()

    def execute_mci_command_on_extmue(self, cmd, cmd_timeout=2):
        """
        Keyword execute mci command and return response.
        :param cmd: Cmd example: forw mte  GetStats [ALL] [COMBINED] [COMBINED]
        :type cmd: str
        :param cmd_timeout: default 2
        :type cmd_timeout: int
        """
        return self._tma.execute_mci_command_on_extmue(cmd, cmd_timeout)
